   var interrupted=data.save(new net.minecraft.nbt.CompoundTag(),l.registryAccess());var entry=interrupted.getList("developments",10).getCompound(0);entry.getCompound("preparationProgress").putString("stage","CAMP_READY");var work=entry.getCompound("preparationProgress").getCompound("work");work.putInt("cursor",0);work.putBoolean("pending",true);var recovery=RemoteDevelopmentData.load(interrupted,l.registryAccess(),l.dimension());h.assertTrue(recovery.find(id).orElseThrow().phase()==Phase.RECOVERY_NEEDED,"Ambiguous work must not replay after loading");
