 private static boolean hill(){return System.getProperty("colonyhorizons.foundationSuite").startsWith("CampPreparationHill");}
 private static boolean largeExcavation(){return water()||cliff()||gap()||hill()||System.getProperty("colonyhorizons.foundationSuite").equals("CampPreparationEndurance");}
 private static boolean gap(){return System.getProperty("colonyhorizons.foundationSuite").equals("CampPreparationGap");}
 private static boolean water(){return System.getProperty("colonyhorizons.foundationSuite").startsWith("CampPreparationWater");}
 private static boolean cliff(){return System.getProperty("colonyhorizons.foundationSuite").equals("CampPreparationCliff");}
